head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf20012";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_datefmt_cal_listStartDd();
        scwin.init_datefmt_cal_listEndDd();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf20012.onpageload' });
    }
};

/**
 * @method
 * @name init_datefmt_cal_listStartDd
 * @description 초기화 — datefmt cal list Start Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_listStartDd = function () { $c.date.checkCalendarFormat("cal_listStartDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_listEndDd
 * @description 초기화 — datefmt cal list End Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_listEndDd = function () { $c.date.checkCalendarFormat("cal_listEndDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cal_listStartDd_onblur
 * @description cal_listStartDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_listStartDd_onblur = async function(e){
    try {
        await scwin.Chk_Date($c.util.getComponent("cal_listStartDd"), '상장 시작일');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf20012.cal_listStartDd_onblur' }); }
};

/**
 * @method
 * @name cal_listEndDd_onblur
 * @description cal_listEndDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_listEndDd_onblur = async function(e){
    try {
        await scwin.Chk_Date($c.util.getComponent("cal_listEndDd"), '상장 종료일');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf20012.cal_listEndDd_onblur' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name Chk_Date
 * @description Chk Date 처리
 * @param {*} Name Name
 * @param {String} Date_Str Date_Str
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Chk_Date = async function (Name, Date_Str) {
    let sdate = Name.getValue(); if (sdate === null) { sdate = ''; }
    pyear = sdate.substr(0, 4);
    pmonth = sdate.substr(4, 2);
    pday = sdate.substr(6, 2);
    src = pyear + '-' + pmonth + '-' + pday;
    syear = parseInt(pyear, 10);
    smonth = parseInt(pmonth, 10) - 1;
    sday = parseInt(pday, 10);
    sodate = new Date(Date.UTC(syear, smonth, sday));
    soyear = (sodate.getYear() < 2000) ? sodate.getYear() + 1900 : sodate.getYear();
    somonth = sodate.getMonth();
    soday = sodate.getDate();
    if (sdate !== "" && (syear !== soyear || smonth !== somonth || sday !== soday)) {
        await $c.win.alert("입력한 " + Date_Str + "이 올바르지 않습니다. \n");
        (Name && Name.setFocus ? Name.setFocus() : (Name && Name.focus ? Name.focus() : void 0));
        return false;
    }
    if (sdate !== "" && sdate.length !== 8) {
        await $c.win.alert("입력한 " + Date_Str + "이 8자리가 아닙니다. \n");
        (Name && Name.setFocus ? Name.setFocus() : (Name && Name.focus ? Name.focus() : void 0));
        return false;
    }
    if (sdate === "") {
        Name.setValue('');
    } else {
        Name.setValue(sdate);
    }
    return true;
};
